diff --git a/xds/src/main/java/io/grpc/xds/internal/matcher/CelCommon.java b/xds/src/main/java/io/grpc/xds/internal/matcher/CelCommon.java
--- a/xds/src/main/java/io/grpc/xds/internal/matcher/CelCommon.java
+++ b/xds/src/main/java/io/grpc/xds/internal/matcher/CelCommon.java
@@ -0,0 +1,134 @@
+/*
+ * Copyright 2026 The gRPC Authors
+ *
+ * Licensed under the Apache License, Version 2.0 (the "License");
+ * you may not use this file except in compliance with the License.
+ * You may obtain a copy of the License at
+ *
+ *     http://www.apache.org/licenses/LICENSE-2.0
+ *
+ * Unless required by applicable law or agreed to in writing, software
+ * distributed under the License is distributed on an "AS IS" BASIS,
+ * WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.
+ * See the License for the specific language governing permissions and
+ * limitations under the License.
+ */
+
+package io.grpc.xds.internal.matcher;
+
+import com.google.common.collect.ImmutableSet;
+import dev.cel.common.CelAbstractSyntaxTree;
+import dev.cel.common.CelOptions;
+import dev.cel.common.ast.CelReference;
+import dev.cel.runtime.CelRuntime;
+import dev.cel.runtime.CelRuntimeFactory;
+import dev.cel.runtime.CelStandardFunctions;
+import dev.cel.runtime.CelStandardFunctions.StandardFunction;
+import dev.cel.runtime.standard.AddOperator.AddOverload;
+import java.util.Map;
+import java.util.regex.Pattern;
+
+/**
+ * Shared utilities for CEL-based matchers and extractors.
+ */
+final class CelCommon {
+  private static final CelOptions CEL_OPTIONS = CelOptions.newBuilder()
+      .enableComprehension(false)
+      .maxRegexProgramSize(100)
+      .build();
+  private static final String REQUEST_VARIABLE = "request";
+  private static final CelStandardFunctions FUNCTIONS = 
+      CelStandardFunctions.newBuilder()
+          .filterFunctions((func, over) -> {
+            if (func == StandardFunction.STRING) {
+              return false;
+            }
+            if (func == StandardFunction.ADD) {
+              return !over.equals(AddOverload.ADD_STRING)
+                  && !over.equals(AddOverload.ADD_LIST);
+            }
+            return true;
+          })
+          .build();
+
+
+
+  private static final ImmutableSet<String> ALLOWED_EXACT_OVERLOAD_IDS = ImmutableSet.of(
+      "equals", "not_equals", "logical_and", "logical_or", "logical_not");
+
+  /**
+   * Regular expression pattern to validate internal CEL overload IDs.
+   *
+   * <p>Standard CEL operators and conversion functions often have empty names in the
+   * AST and are identified solely by their overload IDs (e.g., {@code equals} for
+   * {@code ==}, {@code divide_int64} for {@code /}).
+   *
+   * <p>This pattern matches allowed overload IDs by their prefixes (e.g.,
+   * {@code divide}, {@code size}), optionally followed by numeric types 
+   * (e.g., {@code int64}) and type-specific suffixes (e.g., {@code _string}, 
+   * {@code _int64}).
+   */
+  private static final Pattern ALLOWED_OVERLOAD_ID_PREFIX_PATTERN = Pattern.compile(
+      "^(size|matches|contains|startsWith|endsWith|starts_with|ends_with|"
+          + "timestamp|duration|in|index|has|int|uint|double|string|bytes|bool|"
+          + "less|less_equals|greater|greater_equals|"
+          + "add|subtract|multiply|divide|modulo|negate)"
+          + "[0-9]*(_.*)?$");
+
+  static final CelRuntime RUNTIME = CelRuntimeFactory.standardCelRuntimeBuilder()
+      .setStandardEnvironmentEnabled(false)
+      .setStandardFunctions(FUNCTIONS)
+      .setOptions(CEL_OPTIONS)
+      .build();
+
+  private CelCommon() {}
+
+  /**
+   * Validates that the AST only references the allowed variable ("request")
+   * and supported functions as defined in gRFC A106.
+   */
+  static void checkAllowedReferences(CelAbstractSyntaxTree ast) {
+    for (Map.Entry<Long, CelReference> entry : ast.getReferenceMap().entrySet()) {
+      CelReference ref = entry.getValue();
+
+      // Check for variables (where overloadIds is empty)
+      if (!ref.value().isPresent() && ref.overloadIds().isEmpty()) {
+        if (!REQUEST_VARIABLE.equals(ref.name())) {
+          throw new IllegalArgumentException(
+              "CEL expression references unknown variable: " + ref.name());
+        }
+      } else if (!ref.overloadIds().isEmpty()) {
+        String name = ref.name();
+        if (name.isEmpty()) {
+          boolean allowed = false;
+          for (String id : ref.overloadIds()) {
+            if (id.equals("add_string") || id.equals("add_list") || id.endsWith("_to_string")) {
+              allowed = false;
+              break;
+            }
+            if (ALLOWED_EXACT_OVERLOAD_IDS.contains(id)
+                || ALLOWED_OVERLOAD_ID_PREFIX_PATTERN.matcher(id).matches()) {
+              allowed = true;
+              break;
+            }
+          }
+          if (!allowed) {
+            throw new IllegalArgumentException(
+                "CEL expression references unknown function with overload IDs: "
+                    + ref.overloadIds());
+          }
+        } else {
+          // Standard conversion functions (like string(x)) are named in the AST.
+          // We must explicitly reject 'string' here since it's disabled in the environment.
+          if (name.equals("string")) {
+            throw new IllegalArgumentException(
+                "CEL expression references unknown function with overload IDs: "
+                    + ref.overloadIds());
+          }
+          throw new IllegalArgumentException(
+              "CEL expression references unsupported named function: " + name);
+        }
+      }
+    }
+  }
+}

diff --git a/xds/src/main/java/io/grpc/xds/internal/matcher/CelStringExtractor.java b/xds/src/main/java/io/grpc/xds/internal/matcher/CelStringExtractor.java
--- a/xds/src/main/java/io/grpc/xds/internal/matcher/CelStringExtractor.java
+++ b/xds/src/main/java/io/grpc/xds/internal/matcher/CelStringExtractor.java
@@ -0,0 +1,88 @@
+/*
+ * Copyright 2026 The gRPC Authors
+ *
+ * Licensed under the Apache License, Version 2.0 (the "License");
+ * you may not use this file except in compliance with the License.
+ * You may obtain a copy of the License at
+ *
+ *     http://www.apache.org/licenses/LICENSE-2.0
+ *
+ * Unless required by applicable law or agreed to in writing, software
+ * distributed under the License is distributed on an "AS IS" BASIS,
+ * WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.
+ * See the License for the specific language governing permissions and
+ * limitations under the License.
+ */
+
+package io.grpc.xds.internal.matcher;
+
+import dev.cel.common.CelAbstractSyntaxTree;
+import dev.cel.common.types.SimpleType;
+import dev.cel.runtime.CelEvaluationException;
+import dev.cel.runtime.CelRuntime;
+import dev.cel.runtime.CelVariableResolver;
+import javax.annotation.Nullable;
+
+/**
+ * Executes compiled CEL expressions that extract a string.
+ */
+public final class CelStringExtractor {
+  private final CelRuntime.Program program;
+  @Nullable
+  private final String defaultValue;
+
+  private CelStringExtractor(CelRuntime.Program program, @Nullable String defaultValue) {
+    this.program = program;
+    this.defaultValue = defaultValue;
+  }
+
+  /**
+   * Compiles the AST into a CelStringExtractor with an optional default value.
+   * Throws an Exception if evaluation fails during compilation setup.
+   */
+  public static CelStringExtractor compile(CelAbstractSyntaxTree ast, @Nullable String defaultValue)
+      throws CelEvaluationException {
+    if (ast.getResultType() != SimpleType.STRING && ast.getResultType() != SimpleType.DYN) {
+      throw new IllegalArgumentException(
+          "CEL expression must evaluate to string, got: " + ast.getResultType());
+    }
+    CelCommon.checkAllowedReferences(ast);
+    CelRuntime.Program program = CelCommon.RUNTIME.createProgram(ast);
+    return new CelStringExtractor(program, defaultValue);
+  }
+
+  /**
+   * Compiles the AST into a CelStringExtractor with no default value.
+   * Throws an Exception if evaluation fails during compilation setup.
+   */
+  public static CelStringExtractor compile(CelAbstractSyntaxTree ast)
+      throws CelEvaluationException {
+    return compile(ast, null);
+  }
+
+  /**
+   * Evaluates the CEL expression and returns the string result.
+   * Returns the default value if the result is not a string or if evaluation
+   * fails.
+   */
+  public String extract(Object input) throws CelEvaluationException {
+    if (input instanceof CelVariableResolver) {
+      try {
+        Object result = program.eval((CelVariableResolver) input);
+
+        if (result instanceof String) {
+          return (String) result;
+        }
+      } catch (CelEvaluationException e) {
+        if (defaultValue == null) {
+          throw e;
+        }
+      }
+    } else if (defaultValue == null) {
+      throw new CelEvaluationException(
+          "Unsupported input type for CEL evaluation: "
+              + (input == null ? "null" : input.getClass().getName()));
+    }
+    return defaultValue;
+  }
+}

diff --git a/xds/src/main/java/io/grpc/xds/internal/matcher/GrpcCelEnvironment.java b/xds/src/main/java/io/grpc/xds/internal/matcher/GrpcCelEnvironment.java
--- a/xds/src/main/java/io/grpc/xds/internal/matcher/GrpcCelEnvironment.java
+++ b/xds/src/main/java/io/grpc/xds/internal/matcher/GrpcCelEnvironment.java
@@ -0,0 +1,133 @@
+/*
+ * Copyright 2026 The gRPC Authors
+ *
+ * Licensed under the Apache License, Version 2.0 (the "License");
+ * you may not use this file except in compliance with the License.
+ * You may obtain a copy of the License at
+ *
+ *     http://www.apache.org/licenses/LICENSE-2.0
+ *
+ * Unless required by applicable law or agreed to in writing, software
+ * distributed under the License is distributed on an "AS IS" BASIS,
+ * WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.
+ * See the License for the specific language governing permissions and
+ * limitations under the License.
+ */
+
+package io.grpc.xds.internal.matcher;
+
+import com.google.common.collect.ImmutableSet;
+import dev.cel.runtime.CelVariableResolver;
+import io.grpc.Metadata;
+import java.util.AbstractMap;
+import java.util.Optional;
+import java.util.Set;
+import javax.annotation.Nullable;
+
+/**
+ * CEL Environment for gRPC xDS matching.
+ */
+final class GrpcCelEnvironment implements CelVariableResolver {
+  private final MatchContext context;
+
+  GrpcCelEnvironment(MatchContext context) {
+    this.context = context;
+  }
+
+  @Override
+  public Optional<Object> find(String name) {
+    if (name.equals("request")) {
+      return Optional.of(new LazyRequestMap(this));
+    }
+    return Optional.empty();
+  }
+
+  @Nullable
+  private Object getRequestField(String requestField) {
+    switch (requestField) {
+      case "headers": return new HeadersWrapper(context);
+      case "host": return orEmpty(context.getHost());
+      case "id": return getHeader("x-request-id"); 
+      case "method": return or(context.getMethod(), "POST");
+      case "path":
+      case "url_path":
+        return orEmpty(context.getPath());
+      case "query": return "";
+      case "scheme": return "";
+      case "protocol": return "";
+      case "time": return null;
+      case "referer": return getHeader("referer");
+      case "useragent": return getHeader("user-agent");
+
+      default:
+        return null; 
+    }
+  }
+
+  private String getHeader(String key) {
+    Metadata metadata = context.getMetadata();
+    Iterable<String> values = metadata.getAll(
+        Metadata.Key.of(key, Metadata.ASCII_STRING_MARSHALLER));
+    if (values == null) {
+      return "";
+    }
+    return String.join(",", values);
+  }
+  
+  private static String orEmpty(@Nullable String s) {
+    return s == null ? "" : s;
+  }
+
+  private static String or(@Nullable String s, String def) {
+    return s == null ? def : s;
+  }
+
+  private static final class LazyRequestMap extends AbstractMap<String, Object> {
+    private static final Set<String> KNOWN_KEYS = ImmutableSet.of(
+        "headers", "host", "id", "method", "path", "url_path", "query", "scheme", "protocol",
+        "referer", "useragent", "time");
+    private final GrpcCelEnvironment resolver;
+
+    LazyRequestMap(GrpcCelEnvironment resolver) {
+      this.resolver = resolver;
+    }
+
+    @Override
+    public Object get(Object key) {
+      if (key instanceof String) {
+        Object val = resolver.getRequestField((String) key);
+        if (val == null) {
+          return null;
+        }
+        return val;
+      }
+      return null;
+    }
+
+    @Override
+    public boolean containsKey(Object key) {
+      boolean contains = key instanceof String && KNOWN_KEYS.contains(key);
+      return contains;
+    }
+
+    @Override
+    public Set<String> keySet() {
+      return KNOWN_KEYS;
+    }
+
+    @Override
+    public int size() {
+      return KNOWN_KEYS.size();
+    }
+
+    @Override
+    public boolean isEmpty() {
+      return false;
+    }
+
+    @Override
+    public Set<Entry<String, Object>> entrySet() {
+      throw new UnsupportedOperationException("LazyRequestMap does not support entrySet");
+    }
+  }
+}

diff --git a/xds/src/main/java/io/grpc/xds/internal/matcher/HeadersWrapper.java b/xds/src/main/java/io/grpc/xds/internal/matcher/HeadersWrapper.java
--- a/xds/src/main/java/io/grpc/xds/internal/matcher/HeadersWrapper.java
+++ b/xds/src/main/java/io/grpc/xds/internal/matcher/HeadersWrapper.java
@@ -0,0 +1,172 @@
+/*
+ * Copyright 2026 The gRPC Authors
+ *
+ * Licensed under the Apache License, Version 2.0 (the "License");
+ * you may not use this file except in compliance with the License.
+ * You may obtain a copy of the License at
+ *
+ *     http://www.apache.org/licenses/LICENSE-2.0
+ *
+ * Unless required by applicable law or agreed to in writing, software
+ * distributed under the License is distributed on an "AS IS" BASIS,
+ * WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.
+ * See the License for the specific language governing permissions and
+ * limitations under the License.
+ */
+
+package io.grpc.xds.internal.matcher;
+
+import com.google.common.collect.ImmutableSet;
+import com.google.common.io.BaseEncoding;
+import com.google.errorprone.annotations.DoNotCall;
+import io.grpc.Metadata;
+import java.util.AbstractMap;
+import java.util.Set;
+import javax.annotation.Nullable;
+
+/**
+ * A Map view over Metadata and MatchContext for CEL attribute resolution.
+ * Supports efficient lookup of headers and pseudo-headers without unnecessary copying.
+ */
+final class HeadersWrapper extends AbstractMap<String, String> {
+  private static final ImmutableSet<String> PSEUDO_HEADERS =
+      ImmutableSet.of(":method", ":authority", ":path");
+  private final MatchContext context;
+
+  HeadersWrapper(MatchContext context) {
+    this.context = context;
+  }
+
+  @Override
+  @Nullable
+  public String get(Object key) {
+    if (!(key instanceof String)) {
+      return null;
+    }
+    String headerName = ((String) key).toLowerCase(java.util.Locale.ROOT);
+    // The "te" header is a hop-by-hop header used for protocol signaling (trailers).
+    // Per gRFC A41, it must be treated as not present to prevent matching logic
+    // from depending on transport-level semantics.
+    if (headerName.equals("te")) {
+      return null;
+    }
+    switch (headerName) {
+      case ":method": return context.getMethod();
+      case ":authority": return context.getHost();
+      case "host": return context.getHost();
+      case ":path": return context.getPath();
+      default: return getHeader(headerName);
+    }
+  }
+
+  @Nullable
+  private String getHeader(String headerName) {
+    try {
+      if (headerName.endsWith(Metadata.BINARY_HEADER_SUFFIX)) {
+        Iterable<byte[]> values = context.getMetadata().getAll(
+            Metadata.Key.of(headerName, Metadata.BINARY_BYTE_MARSHALLER));
+        if (values == null) {
+          return null;
+        }
+        StringBuilder sb = new StringBuilder();
+        boolean first = true;
+        for (byte[] value : values) {
+          if (!first) {
+            sb.append(",");
+          }
+          first = false;
+          sb.append(BaseEncoding.base64().omitPadding().encode(value));
+        }
+        return sb.toString();
+      }
+      Metadata metadata = context.getMetadata();
+      Iterable<String> values = metadata.getAll(
+          Metadata.Key.of(headerName, Metadata.ASCII_STRING_MARSHALLER));
+      if (values == null) {
+        return null;
+      }
+      return String.join(",", values);
+    } catch (IllegalArgumentException e) {
+      // Catching IllegalArgumentException and returning null matches Envoy's behavior
+      // (returning an empty optional for invalid header names).
+      return null;
+    }
+  }
+
+  @Override
+  public boolean containsKey(Object key) {
+    if (!(key instanceof String)) {
+      return false;
+    }
+    String headerName = ((String) key).toLowerCase(java.util.Locale.ROOT);
+    if (headerName.equals("te")) {
+      return false;
+    }
+    if (PSEUDO_HEADERS.contains(headerName) || headerName.equals("host")) {
+      return true;
+    }
+    try {
+      if (headerName.endsWith(Metadata.BINARY_HEADER_SUFFIX)) {
+        return context.getMetadata().containsKey(
+            Metadata.Key.of(headerName, Metadata.BINARY_BYTE_MARSHALLER));
+      }
+      return context.getMetadata().containsKey(
+          Metadata.Key.of(headerName, Metadata.ASCII_STRING_MARSHALLER));
+    } catch (IllegalArgumentException e) {
+      return false;
+    }
+  }
+
+  private boolean isMetadataKeyResolvable(String headerName) {
+    try {
+      if (headerName.endsWith(Metadata.BINARY_HEADER_SUFFIX)) {
+        Metadata.Key.of(headerName, Metadata.BINARY_BYTE_MARSHALLER);
+      } else {
+        Metadata.Key.of(headerName, Metadata.ASCII_STRING_MARSHALLER);
+      }
+      return true;
+    } catch (IllegalArgumentException e) {
+      return false;
+    }
+  }
+
+  @Override
+  public Set<String> keySet() {
+    ImmutableSet.Builder<String> builder = ImmutableSet.builder();
+    for (String key : context.getMetadata().keys()) {
+      String lowerKey = key.toLowerCase(java.util.Locale.ROOT);
+      // Filter out any keys we provide specialized aliases/values for.
+      if (!lowerKey.equals("te") 
+          && !lowerKey.equals("host") 
+          && !PSEUDO_HEADERS.contains(lowerKey)
+          && isMetadataKeyResolvable(lowerKey)) {
+        builder.add(key);
+      }
+    }
+    builder.addAll(PSEUDO_HEADERS);
+    builder.add("host");
+    return builder.build();
+  }
+
+  @Override
+  public int size() {
+    int count = 0;
+    for (String key : context.getMetadata().keys()) {
+      String lowerKey = key.toLowerCase(java.util.Locale.ROOT);
+      if (!lowerKey.equals("te") 
+          && !lowerKey.equals("host") 
+          && !PSEUDO_HEADERS.contains(lowerKey)
+          && isMetadataKeyResolvable(lowerKey)) {
+        count++;
+      }
+    }
+    return count + PSEUDO_HEADERS.size() + 1; // +1 for "host" alias
+  }
+
+  @Override
+  @DoNotCall("Always throws UnsupportedOperationException")
+  public Set<Entry<String, String>> entrySet() {
+    throw new UnsupportedOperationException(
+        "Should not be called to prevent resolving all header values.");
+  }
+}

